        Opcode::ModuleBuiltin | Opcode::GetModuleVariable | Opcode::NewTemplateObject | Opcode::SuperGet | Opcode::ToObject | Opcode::ToThis
        | Opcode::Results | Opcode::ResultAt | Opcode::CatchValue | Opcode::IteratorResume | Opcode::ForInStep | Opcode::Yield
        | Opcode::ModuleNamespace | Opcode::RequireModule | Opcode::ResolveModule | Opcode::RequireDynamic | Opcode::ResolveDynamic
