        Opcode::Data | Opcode::NewClosure | Opcode::NewObject | Opcode::NewDictionary | Opcode::NewArray | Opcode::NewRegExp | Opcode::NewRuntimeError
        | Opcode::NewSuppressedError | Opcode::CreateUnmappedArguments | Opcode::CreateMappedArguments | Opcode::CopyObject | Opcode::NewClassToken
